<?php
function inOffPeak(string $tsUTC, ?array $offPeak): bool
{
    if ($offPeak === null) { return false; }
    // parse H:M
    [$hs, $ms] = explode(':', $offPeak['window_start']);
    [$he, $me] = explode(':', $offPeak['window_end']);
    $start = ((int)$hs * 60) + (int)$ms;
    $end = ((int)$he * 60) + (int)$me;
    // extract time-of-day from ISO ts
    [$date, $timeStr] = array_pad(explode(' ', $tsUTC), 2, null);
    $t = preg_match('/T(\d{2}):(\d{2}):(\d{2})/', $tsUTC, $m) ? ((int)$m[1] * 60 + (int)$m[2]) : 0;
    if ($start <= $end) {
        return $t >= $start && $t < $end;
    }
    // crosses midnight
    return $t >= $start || $t < $end;
}
